<?= App\Core\Csrf::field() ?><div class="row g-3"><div class="col-md-4"><label for="booking-customer">Müşteri</label><select id="booking-customer" name="customer_id" class="form-select" required><option value="">Müşteri seçin</option><?php foreach($customers as $customer): ?><option value="<?= (int)$customer['id'] ?>" <?= (string)($oldInput['customer_id'] ?? '')===(string)$customer['id'] ? 'selected' : '' ?>><?= e($customer['name'].' · '.$customer['email']) ?></option><?php endforeach ?></select></div><div class="col-md-4"><label for="booking-service">Hizmet</label><select id="booking-service" name="service_id" class="form-select" required><option value="">Hizmet seçin</option><?php foreach($services as $service): if(!$service['is_active']){continue;} ?><option value="<?= (int)$service['id'] ?>" <?= (string)($oldInput['service_id'] ?? '')===(string)$service['id'] ? 'selected' : '' ?>><?= e($service['name'].' · '.$service['duration_minutes'].' dk · '.$money($service['price'])) ?></option><?php endforeach ?></select></div><div class="col-md-4"><label for="booking-employee">Çalışan</label><select id="booking-employee" name="employee_id" class="form-select" required><option value="">Çalışan seçin</option><?php foreach($employees as $employee): if(!$employee['is_active'] || !$employee['account_active']){continue;} $workerServices=array_column(App\Models\AdminRepository::rows('SELECT service_id FROM employee_services WHERE employee_id=?',[$employee['id']]),'service_id'); ?><option value="<?= (int)$employee['id'] ?>" data-services="<?= e(implode(',',$workerServices)) ?>" <?= (string)($oldInput['employee_id'] ?? '')===(string)$employee['id'] ? 'selected' : '' ?>><?= e($employee['name'].' · '.$employee['title']) ?></option><?php endforeach ?></select></div></div>
<div class="row g-3 mt-1"><div class="col-md-4"><label for="booking-date">Tarih</label><input id="booking-date" type="date" class="form-control" min="<?= date('Y-m-d') ?>" max="<?= date('Y-m-d',strtotime('+365 days')) ?>" value="<?= date('Y-m-d',strtotime('+1 day')) ?>" required></div><div class="col-md-8"><label for="booking-start">Başlangıç zamanı</label><input id="booking-start" name="start_at" type="datetime-local" class="form-control" value="<?= e(is_string($oldInput['start_at'] ?? null) ? str_replace(' ','T',$oldInput['start_at']) : '') ?>" required><small>Hizmet süresi kadar uygun bir aralık seçilmelidir. Sunucu kayıttan önce tekrar doğrular.</small></div></div><button type="button" class="btn btn-outline-dark mt-3" id="load-slots">Müsait saatleri göster</button><div id="slot-message" role="status" class="mt-3 muted"></div><div id="slots" class="slot-grid" aria-label="Müsait saatler"></div><button type="submit" class="btn btn-lumera mt-4">Randevu oluştur</button></form><noscript><p>Başlangıç zamanını elle girebilirsiniz. Tüm müsaitlik kuralları sunucuda doğrulanır.</p></noscript></section>
<section class="admin-card"><h2>Randevu listesi</h2><form method="get" action="<?= e(url('admin/appointments')) ?>" class="filter-row mb-4"><div><label for="filter-date">Tarih</label><input id="filter-date" type="date" name="date" class="form-control" value="<?= e($date) ?>"></div><div><label for="filter-status">Durum</label><select id="filter-status" name="status" class="form-select"><option value="">Tümü</option><?php foreach($statusLabels as $key=>$label): ?><option value="<?= e($key) ?>" <?= $status===$key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach ?></select></div><button type="submit" class="btn btn-lumera">Filtrele</button><a class="btn btn-outline-dark" href="<?= e(url('admin/appointments')) ?>">Temizle</a></form><p class="muted">En yeni 500 kayıt gösterilir. Daha eski kayıtlar için tarih filtresi kullanın.</p><?php $showActions=true; require __DIR__.'/_appointments.php'; ?></section>
